rows=[];events=[]
for i,m in enumerate(items,1):
 env,heading,label,statement=m.groups();key=label[2:]
 nxt=items[i].start() if i<len(items) else len(tex)
 proof=tex[m.end():nxt]
 cites=[]
 for c in re.findall(r'\\cite(?:\[[^\]]*\])?\{([^}]+)\}',statement+proof):cites.extend(c.split(','))
 refs=re.findall(r'\\ref\{([^}]+)\}',statement+proof)
 deps=list(dict.fromkeys(refs+cites))
 if re.fullmatch(r'subject[0-9]+',key):
  n=int(key[7:]);page=2 if n<=11 else 3 if n<=19 else 4 if n<=24 else 5
 elif key.startswith('PM'):page=4
 elif key in ['trace','square','alb-kernel']:page=5
 elif key in ['unipotent-homotopy','formal-homotopy','integral-affinization','Lie-comparison-counterexample','Lie-comparison-integral-counterexample','specialization','strong-approximation','nonlinear-Artin','pointless','Boolean-localization','Picard-general','Picard-double-fibre','descent-counterexample','descent-criterion']:page=3
 elif key=='p-Euler':page=2
 else:page=4
 status='Known' if heading.startswith('Known') else 'Refuted' if heading.startswith('Refuted') else 'Proved'
 body=' '.join(statement.strip().split())
 ident=f'B.{i:02d}'
 line=tex[:m.start()].count('\n')+1
 row=dict(id=ident,statement=body,status=status,where_proved=f'sections/part_B.tex, label {label}',depends_on='; '.join(deps),manuscript_pages=f'66/00{page}',notes=notes[key])
 rows.append(row)
 events.append([f'{ident} / {label}','2026-11-19','GPT-6 Astra (OpenAI), inherited reasoning effort, run /root/cycles_b, ChatGPT Pro mode','targeted proof check',f'{status}; {notes[key]}'])
with (root/'B_results.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['id','statement','status','where_proved','depends_on','manuscript_pages','notes']);w.writeheader();w.writerows(rows)
